// ============================================
// SHARED ACCOUNTING HELPERS
// ============================================
function getSaleTotalAmount(sale) {
    return parseFloat(sale?.total_amount ?? sale?.grandTotal ?? 0) || 0;
}

function getSalePaidAmount(sale) {
    const explicitPaid = parseFloat(sale?.paid_amount ?? sale?.paid ?? 0) || 0;
    if (explicitPaid > 0) return explicitPaid;

    // Backward compatibility: older records may store the payment only in linked collections.
    const saleId = sale?.id;
    if (!saleId) return 0;

    try {
        if (typeof collections !== 'undefined' && Array.isArray(collections)) {
            return collections
                .filter(c => (c.sale_id || c.saleId) == saleId)
                .reduce((sum, c) => sum + (parseFloat(c.amount || 0) || 0), 0);
        }
    } catch (e) {}

    return 0;
}

function getSaleDueAmount(sale) {
    if (!sale) return 0;
    const total = getSaleTotalAmount(sale);
    const paid = getSalePaidAmount(sale);
    const derivedDue = Math.max(0, total - paid);
    const explicitDue = sale.due_amount ?? sale.due;
    if (explicitDue === undefined || explicitDue === null || explicitDue === '') {
        return derivedDue;
    }
    const parsedDue = Math.max(0, parseFloat(explicitDue) || 0);
    return total > 0 ? derivedDue : parsedDue;
}

function getGeneralCollectionAmount(collections, customerId) {
    if (!Array.isArray(collections)) return 0;
    return collections
        .filter(c => (c.customer_id || c.customerId) == customerId && !(c.sale_id || c.saleId))
        .reduce((sum, c) => sum + (parseFloat(c.amount || 0) || 0), 0);
}

function getCustomerFinancialSummary(customerId, sales = [], collections = [], customers = []) {
    const openingBalance = parseFloat(customers.find(c => c.id == customerId)?.opening_balance || 0) || 0;
    const customerSales = Array.isArray(sales) ? sales.filter(s => (s.customer_id || s.customerId) == customerId) : [];
    const salesTotal = customerSales.reduce((sum, sale) => sum + getSaleTotalAmount(sale), 0);
    const paidOnSales = customerSales.reduce((sum, sale) => sum + getSalePaidAmount(sale), 0);
    const dueOnSales = customerSales.reduce((sum, sale) => sum + getSaleDueAmount(sale), 0);
    const generalCollections = getGeneralCollectionAmount(collections, customerId);
    const currentDue = Math.max(0, openingBalance + dueOnSales - generalCollections);
    return {
        openingBalance,
        salesTotal,
        paidOnSales,
        dueOnSales,
        generalCollections,
        currentDue,
        totalPaid: paidOnSales + generalCollections,
    };
}

