function getSharedNavKey() {
    const page = (location.pathname.split('/').pop() || '').toLowerCase();
    if (page === 'index.html' || page === '' || page === '/') return 'index';
    if (page.startsWith('customer')) return 'customers';
    if (page.startsWith('sale-detail')) return 'sales';
    if (page.startsWith('pos')) return 'pos';
    if (page.startsWith('sales')) return 'sales';
    if (page.startsWith('collection')) return 'collections';
    if (page.startsWith('expense')) return 'expenses';
    if (page.startsWith('product')) return 'products';
    if (page.startsWith('staff')) return 'staff';
    if (page.startsWith('supplier')) return 'suppliers';
    if (page.startsWith('report')) return 'reports';
    if (page.startsWith('printer-setting')) return 'printer';
    return '';
}

function isLoginPage() {
    const page = (location.pathname.split('/').pop() || '').toLowerCase();
    return page === 'login.html';
}

